// План specs/addresses.md 3.7–3.8 (кейс AD-10). Android (Pixel 7). Admin, компания «test». Только просмотр.
// В мобильной карточке Clients адрес визуально обрезан (truncate) — проверяем полный текст из DOM (getByText/textContent).
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, setEnglish } from './address-helpers';
import {
  TEST_CLIENT_ADDRESS, TEST_CLIENT_ID, expectNoBrokenUnitFormat, expectUnitRightAfterStreet, jobEntryText, openCustomerJobs, pickAddress, textOf,
} from './address-display-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Адрес: Unit на Android — Clients и страница клиента (#b2f74544)', () => {
  test('Clients on Android: the client card address has Unit right after the street #b2f74544 @android @prod-safe', async ({ page }) => {
    await setEnglish(page);
    await page.goto('/customers');

    const cardAddress = page.locator('main').getByText(TEST_CLIENT_ADDRESS).filter({ visible: true }).first();
    await expect(cardAddress).toBeVisible();
    const full = (await cardAddress.textContent()) ?? '';
    expectUnitRightAfterStreet(pickAddress(full, '2221 NW Federal Hwy'), 'Clients (Android), карточка «test»');

    expectNoBrokenUnitFormat((await page.locator('main').textContent()) ?? '', 'Clients (Android)');
  });

  test('Customer page on Android: header and Jobs tab show Unit right after the street #b2f74544 @android @prod-safe', async ({ page }) => {
    await setEnglish(page);
    await openCustomerJobs(page, TEST_CLIENT_ID, 'JOB-0011');

    const text = await textOf(page.locator('main'), TEST_CLIENT_ADDRESS);
    const header = text.split('\n').map((l) => l.trim()).find((l) => TEST_CLIENT_ADDRESS.test(l)) ?? '';
    expectUnitRightAfterStreet(header.slice(header.indexOf('2221')), 'Шапка клиента «test» (Android)');

    const entry = await jobEntryText(page, 'JOB-0011', '2221 NW Federal Hwy');
    expect(entry, 'JOB-0011').toContain('2221 NW Federal Hwy, Unit 1234, Stuart, FL 34994, USA');
    expectNoBrokenUnitFormat(text, 'Страница клиента «test» (Android)');
  });
});
